package packages;

public class Task_7 {
// Multiplication table of n using for loop
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int table = 2, upto = 10;
		for (int i = 1; i <= upto; i++) {
			System.out.println(table + "*" + i + "=" + table * i);
		}
	}

}
